import { RecordStoreContext } from '../../../../shared/application/ports/record-store.port';
import {
  AuditAccess,
  AuditEventInput,
  AuditObject,
  AuditObjectKind,
  AuditQuery,
  AuditRecordView,
  AuditScope,
  auditData,
  auditFailure,
  auditScope,
  auditStrings,
  auditText,
} from '../../domain/audit-contracts';
import { canonicalAudit, normalizeAudit } from '../../domain/services/audit-data.service';
import {
  AuditAppendPort,
  AuditClockPort,
  AuditCryptoPort,
  AuditRepositoryPort,
} from '../ports/audit-engine.ports';
import { AuditRecord, auditSeal } from '../../domain/aggregates/audit-record';
export class AuditCore implements AuditAppendPort {
  constructor(
    readonly repository: AuditRepositoryPort,
    readonly crypto: AuditCryptoPort,
    readonly clock: AuditClockPort,
  ) {}
  async append(input: AuditEventInput, context?: RecordStoreContext) {
    const event = normalizeAudit(input, this.clock.now());
    const scope = auditScope(event.scope === 'TENANT' ? Number(event.tenantId) : null);
    return this.repository.transaction(scope, (tx) => this.persist(scope, event, tx), context);
  }
  private async persist(scope: AuditScope, event: AuditEventInput, tx: RecordStoreContext) {
    const inputHash = this.crypto.hash(canonicalAudit(event)),
      old = await this.repository.byEvent(scope, event.sourceId, event.eventId, tx);
    if (old) {
      if (old.inputHash !== inputHash)
        throw auditFailure('Audit event identity was reused with different data.', 409);
      return {
        auditRecordId: old.id,
        sequence: old.sequence,
        recordHash: old.recordHash,
        duplicate: true,
      };
    }
    const policies = await this.repository.objects(scope, 'POLICY', tx),
      policy = policies
        .filter(
          (p) =>
            p.status === 'ACTIVE' && (!p.data.eventType || p.data.eventType === event.eventType),
        )
        .sort((a, b) => Number(b.data.version) - Number(a.data.version))[0];
    const severity = policy?.data.severity
      ? auditText(policy.data.severity, 'policy severity')
      : event.severity;
    if (!['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'].includes(severity))
      throw auditFailure('Invalid audit policy.');
    const sensitive =
      event.sensitivity === 'SENSITIVE' ||
      policy?.data.sensitive === true ||
      ['PAYROLL', 'FINANCIAL'].includes(event.category);
    const head = await this.repository.head(scope, tx),
      sequence = head.sequence + 1;
    if (!Number.isSafeInteger(sequence)) throw auditFailure('Audit sequence exhausted.');
    const row: AuditRecordView = {
      ...scope,
      id: this.clock.id(),
      eventId: event.eventId,
      sourceId: event.sourceId,
      sequence,
      schemaVersion: 1,
      eventType: event.eventType,
      category: event.category,
      severity: severity as AuditRecordView['severity'],
      outcome: event.outcome,
      actorId: event.actor.actorId || null,
      resourceType: event.resource.resourceType,
      resourceId: event.resource.resourceId,
      correlationId: event.correlationId || null,
      sensitivity: sensitive ? 'SENSITIVE' : 'STANDARD',
      occurredAt: event.occurredAt,
      receivedAt: this.clock.now().toISOString(),
      policyVersion: policy ? Number(policy.data.version) : 1,
      inputHash,
      previousHash: head.recordHash,
      payloadHash: '',
      recordHash: '',
      payload: event,
    };
    row.payloadHash = this.crypto.hash(canonicalAudit(auditSeal(row)));
    row.recordHash = this.crypto.hash(`${row.previousHash}\n${row.payloadHash}`);
    await this.repository.insert(new AuditRecord(row).toPrimitives(), tx);
    await this.repository.advance({ ...scope, sequence, recordHash: row.recordHash }, tx);
    await this.createObject(
      scope,
      'OUTBOX',
      row.id,
      'PENDING',
      { eventType: 'audit.record.persisted', recordId: row.id, recordHash: row.recordHash },
      tx,
    );
    const rules = await this.repository.objects(scope, 'ALERT_RULE', tx);
    const matched = rules.filter(
      (rule) =>
        rule.status === 'ACTIVE' &&
        Number(rule.data.threshold || 1) <= 1 &&
        (!rule.data.eventType || rule.data.eventType === event.eventType) &&
        (!rule.data.outcome || rule.data.outcome === event.outcome) &&
        (!rule.data.severity || rule.data.severity === row.severity),
    );
    if (row.severity === 'CRITICAL' || event.outcome === 'DENIED' || matched.length) {
      await this.createObject(
        scope,
        'ALERT',
        row.id,
        'OPEN',
        {
          recordId: row.id,
          severity: row.severity,
          ruleIds: matched.map((r) => r.id),
          eventType: row.eventType,
          outcome: row.outcome,
        },
        tx,
      );
    }
    return { auditRecordId: row.id, sequence, recordHash: row.recordHash, duplicate: false };
  }
  createObject(
    scope: AuditScope,
    kind: AuditObjectKind,
    key: string,
    status: string,
    data: Record<string, unknown>,
    tx: RecordStoreContext,
  ) {
    const now = this.clock.now().toISOString();
    return this.repository.createObject(
      { ...scope, id: this.clock.id(), kind, key, status, data, createdAt: now, updatedAt: now },
      tx,
    );
  }
  async requireObject(
    scope: AuditScope,
    kind: AuditObjectKind,
    id: string,
    tx: RecordStoreContext,
  ) {
    const row = await this.repository.object(scope, kind, id, tx);
    if (!row) throw auditFailure('Audit resource not found.', 404);
    return row;
  }
  assertRecordAccess(record: AuditRecordView, access: AuditAccess) {
    if (
      record.scopeKey !== access.scopeKey ||
      (access.ownOnly &&
        (record.actorId !== String(access.actorId) ||
          !['USER', 'AUTH_SESSION', 'user', 'session'].includes(record.resourceType) ||
          (record.resourceType.toLowerCase() === 'user' &&
            record.resourceId !== String(access.actorId))))
    )
      throw auditFailure('Audit record not found.', 404);
    if (record.sensitivity === 'SENSITIVE' && !access.sensitive)
      throw auditFailure('Sensitive audit permission required.', 403);
  }
  async accessibleRecords(access: AuditAccess, ids: string[], tx: RecordStoreContext) {
    const rows: AuditRecordView[] = [];
    for (const id of [...new Set(ids)]) {
      const row = await this.repository.record(access, id, tx);
      if (!row) throw auditFailure('Audit record not found.', 404);
      this.assertRecordAccess(row, access);
      rows.push(row);
    }
    return rows;
  }
  notice(
    scope: AuditScope,
    actor: number,
    action: string,
    resourceId: string,
    metadata: Record<string, unknown>,
    tx?: RecordStoreContext,
  ) {
    return this.append(
      {
        eventId: this.clock.id(),
        eventType: action,
        sourceId: 'audit',
        category: action.includes('export') ? 'EXPORT' : 'COMPLIANCE',
        severity: 'MEDIUM',
        scope: scope.companyId === null ? 'PLATFORM' : 'TENANT',
        tenantId: scope.companyId === null ? undefined : String(scope.companyId),
        actor:
          actor > 0
            ? { actorType: 'USER', actorId: String(actor) }
            : { actorType: 'SERVICE', actorId: 'audit-worker' },
        action,
        resource: { resourceType: 'AUDIT', resourceId },
        outcome: 'SUCCESS',
        occurredAt: this.clock.now().toISOString(),
        metadata,
      },
      tx,
    );
  }
  validateQuery(query: AuditQuery): AuditQuery {
    if (
      (query.from && Number.isNaN(new Date(query.from).getTime())) ||
      (query.to && Number.isNaN(new Date(query.to).getTime()))
    )
      throw auditFailure('Invalid audit date range.');
    if (query.from && query.to && new Date(query.from) > new Date(query.to))
      throw auditFailure('Inverted audit date range.');
    if (query.cursor !== undefined && (!Number.isSafeInteger(query.cursor) || query.cursor < 0))
      throw auditFailure('Invalid audit cursor.');
    if (
      query.limit !== undefined &&
      (!Number.isSafeInteger(query.limit) || query.limit < 1 || query.limit > 1000)
    )
      throw auditFailure('Audit query limit must be between 1 and 1000.');
    return query;
  }
  purpose(access: AuditAccess) {
    auditText(access.purpose, 'audit purpose', 2000);
  }
  async objectData(scope: AuditScope, kind: AuditObjectKind, id: string) {
    return this.repository.transaction(scope, (tx) => this.requireObject(scope, kind, id, tx));
  }
  list(scope: AuditScope, kind: AuditObjectKind) {
    return this.repository.transaction(scope, (tx) => this.repository.objects(scope, kind, tx));
  }
}

import {
  AuditAccess,
  AuditManifest,
  AuditRecordView,
  AuditSignature,
  auditData,
  auditFailure,
  auditStrings,
  auditText,
} from '../../domain/audit-contracts';
import { canonicalAudit } from '../../domain/services/audit-data.service';
import { auditSeal } from '../../domain/aggregates/audit-record';
import { AuditEvidenceStoragePort } from '../ports/audit-engine.ports';
import { AuditCore } from './audit-core';
export class AuditEvidenceService {
  constructor(
    private readonly core: AuditCore,
    private readonly storage: AuditEvidenceStoragePort,
  ) {}
  async create(access: AuditAccess, recordIds: string[], investigationId?: string) {
    this.core.purpose(access);
    if (!recordIds.length || recordIds.length > 1000)
      throw auditFailure('Evidence requires between 1 and 1000 records.');
    const records = await this.core.repository.transaction(access, async (tx) => {
      if (investigationId) {
        const investigation = await this.core.requireObject(
          access,
          'INVESTIGATION',
          investigationId,
          tx,
        );
        if (investigation.status !== 'OPEN') throw auditFailure('Investigation closed.', 409);
      }
      return this.core.accessibleRecords(access, recordIds, tx);
    });
    for (const record of records) {
      const digest = this.core.crypto.hash(canonicalAudit(auditSeal(record)));
      if (
        digest !== record.payloadHash ||
        this.core.crypto.hash(`${record.previousHash}\n${digest}`) !== record.recordHash
      )
        throw auditFailure('Cannot package compromised audit records.', 409);
    }
    records.sort((a, b) => a.sequence - b.sequence);
    const id = this.core.clock.id();
    const content = {
      schemaVersion: 1 as const,
      scopeKey: access.scopeKey,
      createdAt: this.core.clock.now().toISOString(),
      purpose: access.purpose,
      records,
      recordIds: records.map((r) => r.id),
      firstSequence: records[0].sequence,
      lastSequence: records[records.length - 1]!.sequence,
    };
    const checksum = this.core.crypto.hash(canonicalAudit(content));
    const signature = this.core.crypto.sign(`prontoequipas:audit:evidence:v1:${checksum}`);
    const manifest: AuditManifest = { ...content, checksum, signature };
    const bytes = Buffer.from(canonicalAudit(manifest)),
      storageKey = await this.storage.put(access.scopeKey, id, bytes);
    return this.core.repository.transaction(access, async (tx) => {
      const row = await this.core.createObject(
        access,
        'EVIDENCE',
        id,
        'READY',
        {
          storageKey,
          checksum,
          fileHash: this.core.crypto.hash(bytes),
          signature,
          recordIds: content.recordIds,
          investigationId: investigationId || null,
          createdBy: access.actorId,
          sensitive: records.some((r) => r.sensitivity === 'SENSITIVE'),
          byteLength: bytes.length,
        },
        tx,
      );
      await this.core.notice(
        access,
        access.actorId,
        'audit.evidence.package-created',
        row.id,
        { checksum, count: records.length, purpose: access.purpose },
        tx,
      );
      return row;
    });
  }
  async verify(access: AuditAccess, id: string) {
    const row = await this.core.objectData(access, 'EVIDENCE', id);
    if (row.data.sensitive === true && !access.sensitive)
      throw auditFailure('Sensitive audit permission required.', 403);
    const bytes = await this.storage.read(auditText(row.data.storageKey, 'storage key', 500));
    const parsed: unknown = JSON.parse(bytes.toString('utf8'));
    const manifest = auditData(parsed),
      sig = auditData(manifest.signature);
    const signature: AuditSignature = {
      algorithm: 'Ed25519',
      keyId: auditText(sig.keyId, 'key id'),
      signature: auditText(sig.signature, 'signature', 1000),
    };
    const { checksum, signature: ignored, ...content } = manifest;
    let valid =
      sig.algorithm === 'Ed25519' &&
      manifest.scopeKey === access.scopeKey &&
      this.core.crypto.hash(bytes) === row.data.fileHash &&
      this.core.crypto.hash(canonicalAudit(content)) === checksum &&
      checksum === row.data.checksum &&
      this.core.crypto.verify(`prontoequipas:audit:evidence:v1:${String(checksum)}`, signature);
    if (!Array.isArray(content.records)) valid = false;
    else
      for (const value of content.records) {
        const data = auditData(value);
        this.core.assertRecordAccess(data as unknown as AuditRecordView, access);
        const payloadHash = this.core.crypto.hash(
          canonicalAudit(auditSeal(data as unknown as AuditRecordView)),
        );
        if (
          payloadHash !== data.payloadHash ||
          this.core.crypto.hash(`${String(data.previousHash)}\n${payloadHash}`) !== data.recordHash
        )
          valid = false;
      }
    await this.core.notice(access, access.actorId, 'audit.evidence.package-verified', id, {
      valid,
      purpose: access.purpose,
    });
    return { valid, checksum: row.data.checksum };
  }
  async download(access: AuditAccess, id: string) {
    const row = await this.core.objectData(access, 'EVIDENCE', id);
    if (row.data.sensitive === true && !access.sensitive)
      throw auditFailure('Sensitive audit permission required.', 403);
    if (!(await this.verify(access, id)).valid)
      throw auditFailure('Evidence integrity failed.', 409);
    const bytes = await this.storage.read(auditText(row.data.storageKey, 'storage key', 500));
    await this.core.notice(access, access.actorId, 'audit.evidence.downloaded', id, {
      purpose: access.purpose,
    });
    return bytes;
  }
}

import {
  AuditAccess,
  AuditQuery,
  auditFailure,
  auditStrings,
  auditText,
} from '../../domain/audit-contracts';
import { AuditExportRequest } from '../../domain/aggregates/audit-export-request';
import { AuditCore } from './audit-core';
import { AuditEvidenceService } from './audit-evidence.service';
export class AuditExportService {
  constructor(
    private readonly core: AuditCore,
    private readonly evidence: AuditEvidenceService,
  ) {}
  async request(access: AuditAccess, filter: AuditQuery) {
    this.core.purpose(access);
    this.core.validateQuery(filter);
    return this.core.repository.transaction(access, async (tx) => {
      const rows = await this.core.repository.records(
        access,
        { ...filter, limit: Math.min(filter.limit || 1000, 1000) },
        tx,
        access,
      );
      if (!rows.length) throw auditFailure('No records match the export criteria.', 422);
      const row = await this.core.createObject(
        access,
        'EXPORT',
        this.core.clock.id(),
        'PENDING_APPROVAL',
        {
          requesterId: access.actorId,
          purpose: access.purpose,
          recordIds: rows.map((r) => r.id),
          sensitive: rows.some((r) => r.sensitivity === 'SENSITIVE'),
          filter,
          requestedAt: this.core.clock.now().toISOString(),
        },
        tx,
      );
      await this.core.notice(
        access,
        access.actorId,
        'audit.export.requested',
        row.id,
        { records: rows.length, purpose: access.purpose },
        tx,
      );
      return row;
    });
  }
  async decide(access: AuditAccess, id: string, approved: boolean, reason: string) {
    return this.core.repository.transaction(access, async (tx) => {
      const row = await this.core.requireObject(access, 'EXPORT', id, tx);
      if (row.data.sensitive === true && !access.sensitive)
        throw auditFailure('Sensitive audit approval required.', 403);
      const data = new AuditExportRequest(row).decide(
        access.actorId,
        approved,
        reason,
        this.core.clock.now().toISOString(),
      );
      const updated = await this.core.repository.updateObject(
        row,
        { status: approved ? 'APPROVED' : 'REJECTED', data },
        tx,
      );
      await this.core.notice(
        access,
        access.actorId,
        approved ? 'audit.export.approved' : 'audit.export.rejected',
        id,
        { reason, purpose: access.purpose },
        tx,
      );
      return updated;
    });
  }
  async execute(access: AuditAccess, id: string) {
    const claimed = await this.core.repository.transaction(access, async (tx) => {
      const row = await this.core.requireObject(access, 'EXPORT', id, tx);
      if (row.status === 'READY') return row;
      if (
        row.status !== 'APPROVED' &&
        !(
          row.status === 'PROCESSING' &&
          Number(row.data.leaseUntil || 0) < this.core.clock.now().getTime()
        )
      )
        throw auditFailure('Export is not approved or is already running.', 409);
      if (row.data.sensitive === true && !access.sensitive)
        throw auditFailure('Sensitive export permission required.', 403);
      return this.core.repository.updateObject(
        row,
        {
          status: 'PROCESSING',
          data: { ...row.data, leaseUntil: this.core.clock.now().getTime() + 300000 },
        },
        tx,
      );
    });
    if (claimed.status === 'READY') return claimed;
    try {
      const ownerAccess = {
        ...access,
        actorId: Number(claimed.data.requesterId),
        purpose: auditText(claimed.data.purpose, 'purpose', 2000),
      };
      const pack = await this.evidence.create(ownerAccess, auditStrings(claimed.data.recordIds));
      return this.core.repository.transaction(access, async (tx) => {
        const row = await this.core.requireObject(access, 'EXPORT', id, tx);
        const updated = await this.core.repository.updateObject(
          row,
          {
            status: 'READY',
            data: {
              ...row.data,
              evidenceId: pack.id,
              completedAt: this.core.clock.now().toISOString(),
              leaseUntil: 0,
            },
          },
          tx,
        );
        await this.core.notice(
          access,
          access.actorId,
          'audit.export.completed',
          id,
          { evidenceId: pack.id },
          tx,
        );
        return updated;
      });
    } catch (error) {
      await this.core.repository.transaction(access, async (tx) => {
        const row = await this.core.requireObject(access, 'EXPORT', id, tx);
        await this.core.repository.updateObject(
          row,
          {
            status: 'APPROVED',
            data: {
              ...row.data,
              errorType: error instanceof Error ? error.name : 'Unknown',
              leaseUntil: 0,
            },
          },
          tx,
        );
      });
      throw error;
    }
  }
  async download(access: AuditAccess, id: string) {
    const row = await this.core.objectData(access, 'EXPORT', id);
    new AuditExportRequest(row).assertDownload(access.actorId);
    const bytes = await this.evidence.download(
      access,
      auditText(row.data.evidenceId, 'evidence id'),
    );
    await this.core.notice(access, access.actorId, 'audit.export.downloaded', id, {
      purpose: access.purpose,
    });
    return bytes;
  }
}

import {
  AuditAccess,
  AuditScope,
  AuditSignature,
  auditData,
  auditFailure,
  auditText,
} from '../../domain/audit-contracts';
import { auditSeal } from '../../domain/aggregates/audit-record';
import { canonicalAudit } from '../../domain/services/audit-data.service';
import { AuditEvidenceStoragePort } from '../ports/audit-engine.ports';
import { AuditCore } from './audit-core';
export class AuditIntegrityService {
  constructor(
    private readonly core: AuditCore,
    private readonly storage: AuditEvidenceStoragePort,
  ) {}
  async checkpoint(access: AuditAccess) {
    const id = this.core.clock.id(),
      head = await this.core.repository.transaction(access, (tx) =>
        this.core.repository.head(access, tx),
      );
    const statement = {
      schemaVersion: 1,
      scopeKey: access.scopeKey,
      sequence: head.sequence,
      recordHash: head.recordHash,
      createdAt: this.core.clock.now().toISOString(),
    };
    const signature = this.core.crypto.sign(
      `prontoequipas:audit:checkpoint:v1:${canonicalAudit(statement)}`,
    );
    const anchorKey = await this.storage.anchor(
      access.scopeKey,
      id,
      Buffer.from(canonicalAudit({ statement, signature })),
    );
    return this.core.repository.transaction(access, async (tx) => {
      const row = await this.core.createObject(
        access,
        'CHECKPOINT',
        id,
        'SEALED',
        { statement, signature, anchorKey, createdBy: access.actorId },
        tx,
      );
      await this.core.notice(
        access,
        access.actorId,
        'audit.integrity.checkpoint-sealed',
        row.id,
        { sequence: head.sequence, anchorKey, purpose: access.purpose },
        tx,
      );
      return row;
    });
  }
  async verify(scope: AuditScope, actor = 0) {
    const head = await this.core.repository.transaction(scope, (tx) =>
      this.core.repository.head(scope, tx),
    );
    const failures: Array<{ sequence: number; code: string }> = [];
    let sequence = 0,
      previous = '0'.repeat(64);
    const anchors = await this.storage.anchors(scope.scopeKey);
    const signed = new Map<number, string>();
    for (const anchor of anchors) {
      try {
        const parsed: unknown = JSON.parse(anchor.bytes.toString('utf8'));
        const data = auditData(parsed),
          statement = auditData(data.statement),
          sig = auditData(data.signature);
        const signature: AuditSignature = {
          algorithm: 'Ed25519',
          keyId: auditText(sig.keyId, 'key id'),
          signature: auditText(sig.signature, 'signature', 1000),
        };
        const n = Number(statement.sequence);
        if (
          sig.algorithm !== 'Ed25519' ||
          statement.scopeKey !== scope.scopeKey ||
          !Number.isSafeInteger(n) ||
          n < 0 ||
          !this.core.crypto.verify(
            `prontoequipas:audit:checkpoint:v1:${canonicalAudit(statement)}`,
            signature,
          )
        )
          throw new Error('Invalid checkpoint signature.');
        signed.set(n, auditText(statement.recordHash, 'checkpoint hash', 64));
        if (n > head.sequence) failures.push({ sequence: n, code: 'HEAD_ROLLBACK' });
      } catch {
        failures.push({ sequence: 0, code: 'INVALID_EXTERNAL_CHECKPOINT' });
      }
    }
    while (sequence < head.sequence) {
      const rows = await this.core.repository.transaction(scope, (tx) =>
        this.core.repository.records(scope, { cursor: sequence, limit: 1000 }, tx),
      );
      const bounded = rows.filter((row) => row.sequence <= head.sequence);
      if (!bounded.length) {
        failures.push({ sequence: sequence + 1, code: 'MISSING_RECORD' });
        break;
      }
      for (const row of bounded) {
        if (row.sequence !== sequence + 1)
          failures.push({ sequence: sequence + 1, code: 'SEQUENCE_GAP' });
        if (row.previousHash !== previous)
          failures.push({ sequence: row.sequence, code: 'PREVIOUS_HASH_MISMATCH' });
        const payloadHash = this.core.crypto.hash(canonicalAudit(auditSeal(row)));
        if (
          payloadHash !== row.payloadHash ||
          this.core.crypto.hash(`${row.previousHash}\n${payloadHash}`) !== row.recordHash
        )
          failures.push({ sequence: row.sequence, code: 'RECORD_HASH_MISMATCH' });
        if (signed.has(row.sequence) && signed.get(row.sequence) !== row.recordHash)
          failures.push({ sequence: row.sequence, code: 'CHECKPOINT_MISMATCH' });
        sequence = row.sequence;
        previous = row.recordHash;
      }
    }
    if (sequence !== head.sequence || previous !== head.recordHash)
      failures.push({ sequence: head.sequence, code: 'HEAD_MISMATCH' });
    const valid = failures.length === 0;
    const result = await this.core.repository.transaction(scope, async (tx) => {
      const report = await this.core.createObject(
        scope,
        'INTEGRITY_RUN',
        this.core.clock.id(),
        valid ? 'VALID' : 'VIOLATION',
        {
          throughSequence: head.sequence,
          checked: sequence,
          failures,
          assurance: anchors.length ? 'SIGNED_CHECKPOINTS' : 'HASH_CHAIN_ONLY',
          actorId: actor,
        },
        tx,
      );
      if (!valid)
        await this.core.createObject(
          scope,
          'ALERT',
          report.id,
          'OPEN',
          {
            type: 'INTEGRITY_VIOLATION',
            severity: 'CRITICAL',
            verificationId: report.id,
            failures,
          },
          tx,
        );
      return report;
    });
    return {
      valid,
      throughSequence: head.sequence,
      assurance: anchors.length ? 'SIGNED_CHECKPOINTS' : 'HASH_CHAIN_ONLY',
      failures,
      verificationId: result.id,
    };
  }
}

import { AuditAccess, auditStrings, auditText } from '../../domain/audit-contracts';
