        access,
        'INVESTIGATION',
        this.core.clock.id(),
        'OPEN',
        {
          title: auditText(title, 'title', 200),
          reason: auditText(reason, 'reason', 2000),
          openedBy: access.actorId,
          recordIds: [],
          events: [
            { type: 'OPENED', actorId: access.actorId, at: this.core.clock.now().toISOString() },
          ],
        },
        tx,
      );
      await this.core.notice(
