import {
  AuditAccess,
  AuditEventInput,
  AuditScope,
  AuditQuery,
  auditData,
  auditFailure,
  auditText,
} from '../../domain/audit-contracts';
import { normalizeAudit, canonicalAudit } from '../../domain/services/audit-data.service';
import { AuditCore } from './audit-core';
import { AuditEventSourcePort } from '../ports/audit-engine.ports';
export class AuditMonitorService {
  constructor(
    private readonly core: AuditCore,
    private readonly source: AuditEventSourcePort,
  ) {}
  async ingest(scope: AuditScope, input: AuditEventInput) {
    try {
      const normalized = normalizeAudit(input, this.core.clock.now());
      if (
        (normalized.scope === 'TENANT' ? `tenant:${normalized.tenantId}` : 'platform') !==
        scope.scopeKey
      )
        throw auditFailure('Audit source tenant mismatch.', 403);
      return await this.core.append(normalized);
    } catch (error) {
      let safe: AuditEventInput | null = null;
      try {
        safe = normalizeAudit(input, this.core.clock.now());
        if ((safe.scope === 'TENANT' ? `tenant:${safe.tenantId}` : 'platform') !== scope.scopeKey)
          safe = null;
      } catch {
        safe = null;
      }
      await this.core.repository.transaction(scope, async (tx) => {
        const key = this.core.crypto.hash(
          canonicalAudit({
            sourceId: String(input.sourceId).slice(0, 200),
            eventId: String(input.eventId).slice(0, 200),
          }),
        );
        const previous = (await this.core.repository.objects(scope, 'INGESTION_FAILURE', tx)).find(
          (row) => row.key === key,
        );
        if (previous) {
          const attempts = Number(previous.data.attempts || 0) + 1;
          await this.core.repository.updateObject(
            previous,
            {
              status: attempts >= 8 ? 'DEAD' : 'RETRY',
              data: {
                ...previous.data,
                attempts,
                nextAttemptAt:
                  this.core.clock.now().getTime() + Math.min(3600000, 2 ** attempts * 10000),
                errorType: error instanceof Error ? error.name : 'Unknown',
              },
            },
            tx,
          );
        } else
          await this.core.createObject(
            scope,
            'INGESTION_FAILURE',
            key,
            safe ? 'RETRY' : 'DEAD',
            {
              event: safe,
              attempts: 1,
              sourceId: input.sourceId,
              eventId: input.eventId,
              nextAttemptAt: this.core.clock.now().getTime() + 20000,
              errorType: error instanceof Error ? error.name : 'Unknown',
            },
            tx,
          );
      });
      return null;
    }
  }
  async drain(scope: AuditScope, reconcile = false) {
    const cursorKey = reconcile ? 'database-reconciliation' : 'database';
    const cursorEntry = (await this.core.list(scope, 'SOURCE_CURSOR')).find(
      (row) => row.key === cursorKey,
    );
    const cursor = typeof cursorEntry?.data.cursor === 'string' ? cursorEntry.data.cursor : null;
    const batch = await this.source.scan(scope, cursor, 500, reconcile);
    let ingested = 0,
      duplicates = 0,
      failed = 0;
    for (const event of batch.events) {
      const result = await this.ingest(scope, event.input);
      if (!result) failed++;
      else if (result.duplicate) duplicates++;
      else ingested++;
    }
    if (!reconcile && this.source.acknowledge)
      await this.source.acknowledge(
        scope,
        batch.events.map((e) => e.input.eventId),
      );
    await this.core.repository.transaction(scope, async (tx) => {
      if (batch.next) {
        const current = (await this.core.repository.objects(scope, 'SOURCE_CURSOR', tx)).find(
          (row) => row.key === cursorKey,
        );
        const position = reconcile && batch.events.length < 500 ? null : batch.next;
        if (current)
          await this.core.repository.updateObject(current, { data: { cursor: position } }, tx);
        else
          await this.core.createObject(
            scope,
            'SOURCE_CURSOR',
            cursorKey,
            'ACTIVE',
            { cursor: position },
            tx,
          );
      }
      if (reconcile)
        await this.core.createObject(
          scope,
          'RECONCILIATION',
          this.core.clock.id(),
          failed ? 'DIFFERENCES' : 'COMPLETED',
          {
            source: 'database',
            scanned: batch.events.length,
            ingested,
            duplicates,
            failed,
            next: batch.next,
            complete: batch.events.length < 500,
          },
          tx,
        );
    });
    return { scanned: batch.events.length, ingested, duplicates, failed, next: batch.next };
  }
  async retry(scope: AuditScope, id: string, force = false) {
    const row = await this.core.objectData(scope, 'INGESTION_FAILURE', id);
    if (row.status === 'RECOVERED') return row;
    if (
      !force &&
      (row.status === 'DEAD' ||
        Number(row.data.nextAttemptAt || 0) > this.core.clock.now().getTime())
    )
      return row;
    if (!row.data.event)
      throw auditFailure('Invalid events must be repaired at their trusted source.', 409);
    const event = auditData(row.data.event) as unknown as AuditEventInput;
    const result = await this.ingest(scope, event);
    if (result)
      return this.core.repository.transaction(scope, (tx) =>
        this.core.repository.updateObject(
          row,
          {
            status: 'RECOVERED',
            data: {
              ...row.data,
              recoveredAt: this.core.clock.now().toISOString(),
              recordId: result.auditRecordId,
            },
          },
          tx,
        ),
      );
    return this.core.objectData(scope, 'INGESTION_FAILURE', id);
  }
  async retryDue(scope: AuditScope) {
    for (const row of await this.core.list(scope, 'INGESTION_FAILURE'))
      if (row.status === 'RETRY') await this.retry(scope, row.id);
  }
  async policy(
    access: AuditAccess,
    input: {
      code: string;
      eventType?: string;
      severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';
      sensitive: boolean;
      reason: string;
    },
  ) {
    return this.core.repository.transaction(access, async (tx) => {
      const versions = (await this.core.repository.objects(access, 'POLICY', tx)).filter(
        (p) => p.data.code === input.code,
      );
      const version = Math.max(0, ...versions.map((v) => Number(v.data.version))) + 1;
      const row = await this.core.createObject(
        access,
        'POLICY',
        `${input.code}:${version}`,
        'ACTIVE',
        { ...input, version, createdBy: access.actorId },
        tx,
      );
      for (const previous of versions.filter((v) => v.status === 'ACTIVE'))
        await this.core.repository.updateObject(previous, { status: 'SUPERSEDED' }, tx);
      await this.core.notice(
        access,
        access.actorId,
        'audit.policy.created',
        row.id,
        { code: input.code, version, reason: input.reason },
        tx,
      );
      return row;
    });
  }
  alertRule(
    access: AuditAccess,
    input: {
      code: string;
      eventType?: string;
      outcome?: string;
      severity?: string;
      threshold: number;
      windowMinutes: number;
    },
  ) {
    return this.core.repository.transaction(access, async (tx) => {
      const row = await this.core.createObject(
        access,
        'ALERT_RULE',
        input.code,
        'ACTIVE',
        { ...input, createdBy: access.actorId },
        tx,
      );
      await this.core.notice(
        access,
        access.actorId,
        'audit.alert-rule.created',
        row.id,
        { code: input.code },
        tx,
      );
      return row;
    });
  }
  async evaluate(scope: AuditScope) {
    for (const rule of (await this.core.list(scope, 'ALERT_RULE')).filter(
      (r) => r.status === 'ACTIVE',
    )) {
      const threshold = Number(rule.data.threshold || 1),
        windowMinutes = Number(rule.data.windowMinutes || 5);
      if (
        !Number.isSafeInteger(threshold) ||
        threshold < 1 ||
        threshold > 1000 ||
        !Number.isFinite(windowMinutes) ||
        windowMinutes <= 0
      )
        throw auditFailure('Invalid alert rule.');
      const now = this.core.clock.now().getTime(),
        key = `${rule.id}:${Math.floor(now / (windowMinutes * 60000))}`;
      await this.core.repository.transaction(scope, async (tx) => {
        if ((await this.core.repository.objects(scope, 'ALERT', tx)).some((a) => a.key === key))
          return;
        const query: AuditQuery = {
          from: new Date(now - windowMinutes * 60000).toISOString(),
          limit: 1000,
        };
        if (typeof rule.data.eventType === 'string') query.eventType = rule.data.eventType;
        if (typeof rule.data.outcome === 'string')
          query.outcome = rule.data.outcome as AuditQuery['outcome'];
        if (typeof rule.data.severity === 'string')
          query.severity = rule.data.severity as AuditQuery['severity'];
        const records = await this.core.repository.records(scope, query, tx);
        if (records.length >= threshold)
          await this.core.createObject(
            scope,
            'ALERT',
            key,
            'OPEN',
            {
              ruleId: rule.id,
              severity: rule.data.severity || 'HIGH',
              count: records.length,
              windowMinutes,
            },
            tx,
          );
      });
    }
  }
}

import { AuditAccess, AuditQuery, auditFailure } from '../../domain/audit-contracts';
import { AuditCore } from './audit-core';
export class AuditQueryService {
  constructor(private readonly core: AuditCore) {}
  async search(access: AuditAccess, query: AuditQuery) {
    this.core.purpose(access);
    this.core.validateQuery(query);
    const data = await this.core.repository.transaction(access, (tx) =>
      this.core.repository.records(access, query, tx, access),
    );
    await this.core.notice(access, access.actorId, 'audit.records.queried', access.scopeKey, {
      purpose: access.purpose,
      filters: query,
      returned: data.length,
    });
    return {
      data,
      nextCursor:
        data.length === Math.min(query.limit || 100, 1000) ? data[data.length - 1]?.sequence : null,
    };
  }
  async get(access: AuditAccess, id: string) {
    this.core.purpose(access);
    const rows = await this.core.repository.transaction(access, (tx) =>
      this.core.accessibleRecords(access, [id], tx),
    );
    await this.core.notice(access, access.actorId, 'audit.record.read', id, {
      purpose: access.purpose,
    });
    return rows[0];
  }
  async dashboard(access: AuditAccess, query: AuditQuery = {}) {
    this.core.purpose(access);
    this.core.validateQuery(query);
    const counters = { events: 0, critical: 0, denied: 0, failures: 0, withoutCorrelation: 0 };
    const categories: Record<string, number> = {};
    let cursor = query.cursor || 0;
    const snapshot = await this.core.repository.transaction(access, (tx) =>
      this.core.repository.head(access, tx),
    );
    while (cursor < snapshot.sequence) {
      const rows = await this.core.repository.transaction(access, (tx) =>
        this.core.repository.records(access, { ...query, cursor, limit: 1000 }, tx, access),
      );
      const bounded = rows.filter((r) => r.sequence <= snapshot.sequence);
      if (!bounded.length) break;
      for (const row of bounded) {
        counters.events++;
        if (row.severity === 'CRITICAL') counters.critical++;
        if (row.outcome === 'DENIED') counters.denied++;
        if (row.outcome === 'FAILURE') counters.failures++;
        if (!row.correlationId) counters.withoutCorrelation++;
        categories[row.category] = (categories[row.category] || 0) + 1;
      }
      cursor = bounded[bounded.length - 1]!.sequence;
    }
    await this.core.notice(access, access.actorId, 'audit.report.read', access.scopeKey, {
      purpose: access.purpose,
    });
    return { ...counters, categories, asOfSequence: snapshot.sequence };
  }
}

import {
  AuditAccess,
  AuditCategory,
  AuditRecordView,
  auditFailure,
  auditStrings,
  auditText,
} from '../../domain/audit-contracts';
import { AuditCore } from './audit-core';
import { AuditEvidenceService } from './audit-evidence.service';
import { AuditIntegrityService } from './audit-integrity.service';
export class AuditRetentionService {
  constructor(
    private readonly core: AuditCore,
    private readonly evidence: AuditEvidenceService,
    private readonly integrity: AuditIntegrityService,
  ) {}
  async policy(
    access: AuditAccess,
    input: { category: AuditCategory; days: number; legalReference: string; reason: string },
  ) {
    if (!Number.isSafeInteger(input.days) || input.days < 1)
      throw auditFailure('A positive retention period must be explicitly approved.');
    return this.core.repository.transaction(access, async (tx) => {
      const versions = (await this.core.repository.objects(access, 'RETENTION', tx)).filter(
        (p) => p.data.category === input.category,
      );
      const version = Math.max(0, ...versions.map((v) => Number(v.data.version))) + 1;
      const row = await this.core.createObject(
        access,
        'RETENTION',
        `${input.category}:${version}`,
        'ACTIVE',
        {
          ...input,
          mode: 'ARCHIVE',
          version,
          createdBy: access.actorId,
          legalReference: auditText(input.legalReference, 'retention authority', 1000),
          reason: auditText(input.reason, 'reason', 2000),
        },
        tx,
      );
      for (const previous of versions.filter((p) => p.status === 'ACTIVE'))
        await this.core.repository.updateObject(previous, { status: 'SUPERSEDED' }, tx);
      await this.core.notice(
        access,
        access.actorId,
        'audit.retention.policy-created',
        row.id,
        { category: input.category, days: input.days, version },
        tx,
      );
      return row;
    });
  }
  hold(
    access: AuditAccess,
    input: {
      reason: string;
      recordIds?: string[];
      resourceType?: string;
      resourceId?: string;
      wholeScope?: boolean;
    },
  ) {
    if (!input.wholeScope && !input.recordIds?.length && !input.resourceType)
      throw auditFailure('Specify records, a resource, or an explicit scope-wide legal hold.');
    return this.core.repository.transaction(access, async (tx) => {
      if (input.recordIds?.length) await this.core.accessibleRecords(access, input.recordIds, tx);
      const row = await this.core.createObject(
        access,
        'LEGAL_HOLD',
        this.core.clock.id(),
        'ACTIVE',
        {
          ...input,
          reason: auditText(input.reason, 'legal hold reason', 2000),
          createdBy: access.actorId,
        },
        tx,
      );
      await this.core.notice(
        access,
        access.actorId,
        'audit.legal-hold.created',
        row.id,
        { reason: input.reason },
        tx,
      );
      return row;
    });
  }
  release(access: AuditAccess, id: string, reason: string) {
    return this.core.repository.transaction(access, async (tx) => {
      const row = await this.core.requireObject(access, 'LEGAL_HOLD', id, tx);
      if (row.status !== 'ACTIVE') throw auditFailure('Legal hold is not active.', 409);
      const updated = await this.core.repository.updateObject(
        row,
        {
          status: 'RELEASED',
          data: {
            ...row.data,
            releasedBy: access.actorId,
            releasedAt: this.core.clock.now().toISOString(),
            releaseReason: auditText(reason, 'release reason', 2000),
          },
        },
        tx,
      );
      await this.core.notice(
        access,
        access.actorId,
        'audit.legal-hold.released',
        id,
        { reason },
        tx,
      );
      return updated;
    });
  }
  async execute(access: AuditAccess, policyId: string) {
    const policy = await this.core.objectData(access, 'RETENTION', policyId);
    if (policy.status !== 'ACTIVE') throw auditFailure('Retention policy is not active.', 409);
    const cutoff = new Date(this.core.clock.now().getTime() - Number(policy.data.days) * 86400000);
    if (Number.isNaN(cutoff.getTime())) throw auditFailure('Invalid retention cutoff.');
    const key = `${policyId}:${cutoff.toISOString().slice(0, 10)}`;
    const previous = (await this.core.list(access, 'RETENTION_RUN')).find((row) => row.key === key);
    if (previous?.status === 'COMPLETED') return previous;
    if (
      previous?.status === 'RUNNING' &&
      Number(previous.data.leaseUntil) > this.core.clock.now().getTime()
    )
      throw auditFailure('Retention execution already running.', 409);
    await this.integrity.checkpoint(access);
    const run = await this.core.repository.transaction(access, async (tx) =>
      previous
        ? this.core.repository.updateObject(
            previous,
            {
              status: 'RUNNING',
              data: { ...previous.data, leaseUntil: this.core.clock.now().getTime() + 600000 },
            },
            tx,
          )
        : this.core.createObject(
            access,
            'RETENTION_RUN',
            key,
            'RUNNING',
            {
              policyId,
              cutoff: cutoff.toISOString(),
              leaseUntil: this.core.clock.now().getTime() + 600000,
            },
            tx,
          ),
    );
    let cursor = 0,
      archived = 0,
      held = 0;
    const packages: string[] = [];
    try {
      while (true) {
        const batch = await this.core.repository.transaction(access, async (tx) => {
          const rows = await this.core.repository.records(
            access,
            {
              category: policy.data.category as AuditCategory,
              to: cutoff.toISOString(),
              cursor,
              limit: 1000,
            },
            tx,
          );
          const holds = (await this.core.repository.objects(access, 'LEGAL_HOLD', tx)).filter(
            (h) => h.status === 'ACTIVE',
          );
          const investigations = (
            await this.core.repository.objects(access, 'INVESTIGATION', tx)
          ).filter((i) => i.status === 'OPEN');
          const records = rows.filter(
            (record) =>
              !holds.some(
                (hold) =>
                  hold.data.wholeScope === true ||
                  (Array.isArray(hold.data.recordIds) && hold.data.recordIds.includes(record.id)) ||
                  (hold.data.resourceType === record.resourceType &&
                    (!hold.data.resourceId || hold.data.resourceId === record.resourceId)),
              ) &&
              !investigations.some(
                (i) => Array.isArray(i.data.recordIds) && i.data.recordIds.includes(record.id),
              ),
          );
          return { rows, records };
        });
        if (!batch.rows.length) break;
        held += batch.rows.length - batch.records.length;
        cursor = batch.rows[batch.rows.length - 1]!.sequence;
        if (batch.records.length) {
          const evidence = await this.evidence.create(
            access,
            batch.records.map((r) => r.id),
          );
          packages.push(evidence.id);
          archived += batch.records.length;
        }
      }
      return this.core.repository.transaction(access, async (tx) => {
        const current = await this.core.requireObject(access, 'RETENTION_RUN', run.id, tx);
        const result = await this.core.repository.updateObject(
          current,
          {
            status: 'COMPLETED',
            data: {
              ...current.data,
              archived,
              held,
              packages,
              deleted: 0,
              mode: 'ARCHIVE',
              completedAt: this.core.clock.now().toISOString(),
              leaseUntil: 0,
            },
          },
          tx,
        );
        await this.core.notice(
          access,
          access.actorId,
          'audit.retention.executed',
          run.id,
          { archived, held, packages, purpose: access.purpose },
          tx,
        );
        return result;
      });
    } catch (error) {
      await this.core.repository.transaction(access, async (tx) => {
        const current = await this.core.requireObject(access, 'RETENTION_RUN', run.id, tx);
        await this.core.repository.updateObject(
          current,
          {
            status: 'FAILED',
            data: {
              ...current.data,
              packages,
              archived,
              held,
              leaseUntil: 0,
              errorType: error instanceof Error ? error.name : 'Unknown',
            },
          },
          tx,
        );
      });
      throw error;
    }
  }
}

import { BadRequestError } from '../../../../shared/errors/app.error';
import { AuditLogRepository } from '../../domain/repositories/audit-log.repository';

export interface QueryAuditLogsInput {
  /** Obrigatório — vem do contexto de tenant, nunca do body. */
  companyId: number;
  page?: number;
  limit?: number;
  action?: string;
  entityType?: string;
  entityId?: string;
  from?: string;
  to?: string;
}

/**
 * Consulta paginada do trilho de auditoria de uma empresa.
 * Todos os filtros são aplicados DENTRO do companyId indicado.
 */
export class QueryAuditLogsUseCase {
  constructor(private readonly repository: AuditLogRepository) {}

  async execute(input: QueryAuditLogsInput) {
    const page = Math.max(1, Number(input.page) || 1);
    const limit = Math.min(100, Math.max(1, Number(input.limit) || 20));

    if (!input.companyId || input.companyId <= 0) {
      throw new BadRequestError('Company context is required.');
    }

    const from = input.from ? new Date(input.from) : undefined;
    const to = input.to ? new Date(input.to) : undefined;

    if (from && Number.isNaN(from.getTime())) {
      throw new BadRequestError('Invalid date filter.');
    }

    if (to && Number.isNaN(to.getTime())) {
      throw new BadRequestError('Invalid date filter.');
    }

    const { rows, total } = await this.repository.list({
      companyId: input.companyId,
      page,
      limit,
      action: input.action || undefined,
      entityType: input.entityType || undefined,
      entityId: input.entityId || undefined,
      from,
      to,
    });

    return {
      data: rows.map((log) => log.toPrimitives()),
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.max(1, Math.ceil(total / limit)),
      },
    };
  }
}

import { AuditObject, auditFailure, auditText } from '../audit-contracts';
export class AuditExportRequest {
  constructor(private readonly record: AuditObject) {
    if (record.kind !== 'EXPORT') throw auditFailure('Invalid export.');
  }
  decide(actor: number, approved: boolean, reason: string, at: string) {
    if (this.record.status !== 'PENDING_APPROVAL')
      throw auditFailure('Export already decided.', 409);
    if (this.record.data.requesterId === actor)
      throw auditFailure('Export approval requires another actor.', 403);
    return {
      ...this.record.data,
      approverId: actor,
      decision: approved ? 'APPROVED' : 'REJECTED',
      reason: auditText(reason, 'decision reason', 2000),
      decidedAt: at,
    };
  }
  assertDownload(actor: number) {
    if (this.record.status !== 'READY' || this.record.data.requesterId !== actor)
      throw auditFailure('Export unavailable.', 404);
  }
}

import { AuditObject, auditFailure, auditStrings, auditText } from '../audit-contracts';
export class AuditInvestigation {
  constructor(private readonly record: AuditObject) {
    if (record.kind !== 'INVESTIGATION') throw auditFailure('Invalid investigation.');
  }
  addEvidence(ids: string[]) {
    if (this.record.status !== 'OPEN') throw auditFailure('Investigation is closed.', 409);
    return {
      ...this.record.data,
      recordIds: [...new Set([...auditStrings(this.record.data.recordIds), ...ids])],
    };
  }
  close(actor: number, reason: string, at: string) {
    if (this.record.status !== 'OPEN') throw auditFailure('Investigation is closed.', 409);
    return {
      ...this.record.data,
      closedBy: actor,
      closedAt: at,
      resolution: auditText(reason, 'resolution', 2000),
    };
  }
}

