let sqliteTail = Promise.resolve();
async function sqliteSerial<T>(operation: () => Promise<T>): Promise<T> {
  let release = () => {};
  const before = sqliteTail;
  sqliteTail = new Promise<void>((resolve) => {
    release = resolve;
  });
  await before;
  try {
    return await operation();
  } finally {
    release();
  }
}
function recordView(model: AuditRecordModel): AuditRecordView {
  const row = model.get({ plain: true });
  return {
    ...row,
    sequence: Number(row.sequence),
    occurredAt: new Date(row.occurredAt).toISOString(),
    receivedAt: new Date(row.receivedAt).toISOString(),
  };
}
function objectView(model: InstanceType<(typeof auditObjectModels)['POLICY']>): AuditObject {
  const row = model.get({ plain: true });
  return {
    ...row,
    createdAt: new Date(row.createdAt).toISOString(),
    updatedAt: new Date(row.updatedAt).toISOString(),
  };
}
export class SequelizeAuditEngineRepository implements AuditRepositoryPort {
  async transaction<T>(
    scope: AuditScope,
    operation: (context: RecordStoreContext) => Promise<T>,
    context?: RecordStoreContext,
  ): Promise<T> {
    if (context) {
      if (recordTransactionTenant(context) !== scope.companyId)
        throw auditFailure('Audit transaction tenant mismatch.', 403);
      await this.lock(scope, resolveRecordTransaction(context)!);
      return operation(context);
    }
    const run = () =>
      sequelize.transaction(async (transaction) => {
        await this.lock(scope, transaction);
        return withRecordTransaction(transaction, scope.companyId, operation);
      });
    return sequelize.getDialect() === 'sqlite' ? sqliteSerial(run) : run();
  }
  private async lock(scope: AuditScope, transaction: Transaction) {
    if (sequelize.getDialect() === 'postgres') {
      await sequelize.query("SELECT set_config('app.current_tenant',:tenant,true)", {
        replacements: { tenant: scope.companyId === null ? '' : String(scope.companyId) },
        type: QueryTypes.SELECT,
        transaction,
      });
      await sequelize.query("SELECT pg_advisory_xact_lock(hashtext('audit'),:tenant)", {
        replacements: { tenant: scope.companyId || 0 },
        transaction,
      });
    }
  }
  async head(scope: AuditScope, context: RecordStoreContext): Promise<AuditHead> {
    const transaction = resolveRecordTransaction(context);
    await AuditScopeCatalogModel.findOrCreate({
      where: { scopeKey: scope.scopeKey },
      defaults: scope,
      transaction,
    });
    await AuditHeadModel.findOrCreate({
      where: { scopeKey: scope.scopeKey },
      defaults: { ...scope, sequence: 0, recordHash: '0'.repeat(64) },
      transaction,
    });
    const row = await AuditHeadModel.findOne({
      where: { ...scope },
      transaction,
      lock: transaction?.LOCK.UPDATE,
    });
    if (!row) throw new Error('Audit head unavailable.');
    const data = row.get({ plain: true });
    return { ...data, sequence: Number(data.sequence) };
  }
  async byEvent(scope: AuditScope, sourceId: string, eventId: string, context: RecordStoreContext) {
    const row = await AuditRecordModel.findOne({
      where: { ...scope, sourceId, eventId },
      transaction: resolveRecordTransaction(context),
    });
    return row ? recordView(row) : null;
  }
  async insert(record: AuditRecordView, context: RecordStoreContext) {
    await AuditRecordModel.create(record, { transaction: resolveRecordTransaction(context) });
  }
  async advance(head: AuditHead, context: RecordStoreContext) {
    const [changed] = await AuditHeadModel.update(
      { sequence: head.sequence, recordHash: head.recordHash },
      {
        where: { scopeKey: head.scopeKey, companyId: head.companyId, sequence: head.sequence - 1 },
        transaction: resolveRecordTransaction(context),
      },
    );
    if (changed !== 1) throw auditFailure('Audit head changed concurrently.', 409);
  }
  async records(
    scope: AuditScope,
    query: AuditQuery,
    context: RecordStoreContext,
    access?: Pick<AuditAccess, 'actorId' | 'sensitive' | 'ownOnly'>,
  ) {
    const where: Record<string | symbol, unknown> = { ...scope };
    for (const field of [
      'eventType',
      'category',
      'severity',
      'outcome',
      'actorId',
      'resourceType',
      'resourceId',
      'correlationId',
    ] as const)
      if (query[field]) where[field] = query[field];
    if (query.cursor !== undefined) where.sequence = { [Op.gt]: query.cursor };
    if (query.from || query.to)
      where.occurredAt = {
        ...(query.from ? { [Op.gte]: new Date(query.from) } : {}),
        ...(query.to ? { [Op.lte]: new Date(query.to) } : {}),
      };
    if (access?.ownOnly) {
      where.actorId = String(access.actorId);
      where[Op.and] = [
        {
          [Op.or]: [
            { resourceType: { [Op.in]: ['USER', 'user'] }, resourceId: String(access.actorId) },
            { resourceType: { [Op.in]: ['AUTH_SESSION', 'session'] } },
          ],
        },
      ];
    }
    if (access && !access.sensitive) where.sensitivity = 'STANDARD';
    return (
      await AuditRecordModel.findAll({
        where: where as WhereOptions,
        order: [['sequence', 'ASC']],
        limit: Math.min(query.limit || 100, 1000),
        transaction: resolveRecordTransaction(context),
      })
    ).map(recordView);
  }
  async record(scope: AuditScope, id: string, context: RecordStoreContext) {
    const row = await AuditRecordModel.findOne({
      where: { ...scope, id },
      transaction: resolveRecordTransaction(context),
    });
    return row ? recordView(row) : null;
  }
  async createObject(object: AuditObject, context: RecordStoreContext) {
    return objectView(
      await auditObjectModels[object.kind].create(object, {
        transaction: resolveRecordTransaction(context),
      }),
    );
  }
  async object(scope: AuditScope, kind: AuditObjectKind, id: string, context: RecordStoreContext) {
    const transaction = resolveRecordTransaction(context),
      row = await auditObjectModels[kind].findOne({
        where: { ...scope, id, kind },
        transaction,
        lock: transaction?.LOCK.UPDATE,
      });
    return row ? objectView(row) : null;
  }
  async objects(scope: AuditScope, kind: AuditObjectKind, context: RecordStoreContext) {
    return (
      await auditObjectModels[kind].findAll({
        where: { ...scope, kind },
        order: [
          ['createdAt', 'ASC'],
          ['id', 'ASC'],
        ],
        transaction: resolveRecordTransaction(context),
      })
    ).map(objectView);
  }
  async updateObject(
    object: AuditObject,
    changes: { status?: string; data?: Record<string, unknown> },
    context: RecordStoreContext,
  ) {
    const row = await auditObjectModels[object.kind].findOne({
      where: { id: object.id, scopeKey: object.scopeKey, companyId: object.companyId },
      transaction: resolveRecordTransaction(context),
    });
    if (!row) throw auditFailure('Audit workflow not found.', 404);
    return objectView(
      await row.update(
        { ...changes, updatedAt: new Date().toISOString() },
        { transaction: resolveRecordTransaction(context) },
      ),
    );
  }
  async scopes() {
    return (await AuditScopeCatalogModel.findAll({ attributes: ['companyId'] })).map((row) =>
      auditScope(row.getDataValue('companyId')),
    );
  }
}

import { promises as fs } from 'fs';
import path from 'path';
import { AuditEvidenceStoragePort } from '../../application/ports/audit-engine.ports';
export class FileAuditEvidenceStorage implements AuditEvidenceStoragePort {
  constructor(
    private readonly root: string,
    private readonly anchorRoot?: string,
  ) {}
  private location(root: string, key: string) {
    const resolved = path.resolve(root, key);
    if (!resolved.startsWith(path.resolve(root) + path.sep))
      throw new Error('Invalid audit storage key.');
    return resolved;
  }
  async put(scopeKey: string, id: string, bytes: Buffer) {
    const key = `${scopeKey.replace(':', '-')}/${id}.json`;
    const file = this.location(this.root, key);
    await fs.mkdir(path.dirname(file), { recursive: true });
    try {
      await fs.writeFile(file, bytes, { flag: 'wx', mode: 0o400 });
    } catch (error) {
      if (!(error instanceof Error) || !('code' in error) || error.code !== 'EEXIST') throw error;
      const current = await fs.readFile(file);
      if (!current.equals(bytes))
        throw new Error('Immutable evidence already exists with different content.');
    }
    return key;
  }
  read(key: string) {
    return fs.readFile(this.location(this.root, key));
  }
  async anchor(scopeKey: string, id: string, bytes: Buffer) {
    if (!this.anchorRoot)
      throw new Error('Configure an independently protected audit checkpoint anchor.');
    const storage = new FileAuditEvidenceStorage(this.anchorRoot);
    return storage.put(scopeKey, id, bytes);
  }
  async anchors(scopeKey: string) {
    if (!this.anchorRoot) return [];
    const directory = scopeKey.replace(':', '-');
    const location = this.location(this.anchorRoot, directory);
    let files: string[];
    try {
      files = await fs.readdir(location);
    } catch (error) {
      if (error instanceof Error && 'code' in error && error.code === 'ENOENT') return [];
      throw error;
    }
    return Promise.all(
      files
        .filter((file) => /^[a-f0-9-]+\.json$/.test(file))
        .map(async (file) => ({
          key: `${directory}/${file}`,
          bytes: await fs.readFile(this.location(this.anchorRoot!, `${directory}/${file}`)),
        })),
    );
  }
}

import { randomUUID } from 'crypto';
import { RequestHandler } from 'express';
import { AuditCore } from '../../application/use-cases/audit-core';
export interface AuditContextRunner {
  run(
    context: {
      requestId: string;
      actor: () => number | undefined;
      company: () => number | undefined;
      ipAddress: string | null;
      userAgent: string | null;
    },
    operation: () => void,
  ): void;
}
export function auditRequestMiddleware(
  core: AuditCore,
  context: AuditContextRunner,
  onFailure: () => void,
): RequestHandler {
  return (req, res, next) => {
    if (process.env.NODE_ENV === 'test' && process.env.AUDIT_HTTP_CAPTURE_ENABLED !== 'true') {
      next();
      return;
    }
    // A server-generated correlation id cannot be spoofed through arbitrary request headers.
    const requestId = randomUUID();
    res.setHeader('X-Request-Id', requestId);
    context.run(
      {
        requestId,
        actor: () => req.user?.userId,
        company: () => req.tenant?.companyId,
        ipAddress: req.ip || null,
        userAgent: req.get('user-agent')?.slice(0, 500) || null,
      },
      () => {
        res.once('finish', () => {
          const denied = res.statusCode === 401 || res.statusCode === 403,
            failed = res.statusCode >= 500;
          const security = /^\/(auth|oauth|sessions)(\/|$)/.test(req.path);
          const sensitiveRead =
            req.method === 'GET' &&
            /^\/(payslips|documents|reports|payments|payroll)(\/|$)/.test(req.path);
          if (!denied && !failed && !security && !sensitiveRead) return;
          const companyId = req.tenant?.companyId ?? null;
          void core
            .append({
              eventId: randomUUID(),
              eventType: denied
                ? 'security.request.denied'
                : failed
                  ? 'request.failed'
                  : sensitiveRead
                    ? 'sensitive-resource.accessed'
                    : 'authentication.request',
              sourceId: 'http',
              category: denied || security ? 'SECURITY' : 'ACCESS',
              severity: denied || failed ? 'HIGH' : 'MEDIUM',
              scope: companyId === null ? 'PLATFORM' : 'TENANT',
              tenantId: companyId === null ? undefined : String(companyId),
              actor: req.user?.userId
                ? { actorType: 'USER', actorId: String(req.user.userId) }
                : { actorType: 'EXTERNAL', actorId: 'anonymous' },
              action: req.method,
              resource: {
                resourceType: 'HTTP',
                resourceId: String(req.route?.path || 'unmatched').slice(0, 200),
              },
              outcome: denied ? 'DENIED' : res.statusCode >= 400 ? 'FAILURE' : 'SUCCESS',
              occurredAt: new Date().toISOString(),
              correlationId: requestId,
              requestId,
              metadata: { status: res.statusCode, method: req.method, ipAddress: req.ip },
            })
            .catch(onFailure);
        });
        next();
      },
    );
  };
}

import { Request, Response, Router } from 'express';
import { z } from 'zod';
import { AuditServices } from '../../application/use-cases/audit-services';
import {
  AuditAccess,
  AuditObjectKind,
  AuditQuery,
  auditCategories,
  auditFailure,
  auditScope,
  auditText,
} from '../../domain/audit-contracts';

export type AuditAuthorize = (
  actorId: number,
  companyId: number | null,
  permission: string,
) => Promise<boolean>;
const text = z.string().trim().min(1).max(200);
const reason = z.string().trim().min(3).max(2000);
const identifiers = z.array(z.string().uuid()).min(1).max(1000);
const querySchema = z.object({
  eventType: text.optional(),
  category: z.enum(auditCategories).optional(),
  severity: z.enum(['CRITICAL', 'HIGH', 'MEDIUM', 'LOW']).optional(),
  outcome: z.enum(['SUCCESS', 'FAILURE', 'DENIED', 'PARTIAL', 'CANCELLED']).optional(),
  actorId: text.optional(),
  resourceType: text.optional(),
  resourceId: text.optional(),
  correlationId: text.optional(),
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  cursor: z.coerce.number().int().min(0).optional(),
  limit: z.coerce.number().int().min(1).max(1000).optional(),
});
const id = (req: Request) => z.string().uuid().parse(req.params.id);

/** The router receives authenticated identity and resolved tenant from the composition root. */
export function createAuditEngineRoutes(
  services: AuditServices,
  authorize: AuditAuthorize,
  platform = false,
): Router {
  const router = Router();
  async function access(req: Request, permission: string, allowOwn = false): Promise<AuditAccess> {
    const actorId = Number(req.user?.userId),
      companyId = platform ? null : req.tenant?.companyId;
    if (!Number.isSafeInteger(actorId) || actorId <= 0)
      throw auditFailure('Authentication required.', 401);
    if (companyId === undefined) throw auditFailure('Resolved tenant required.', 403);
    const permitted = await authorize(actorId, companyId, permission);
    const ownOnly =
      !permitted &&
      allowOwn &&
      !platform &&
      (await authorize(actorId, companyId, 'audit:records:read-own'));
    if (!permitted && !ownOnly) throw auditFailure('Audit permission denied.', 403);
    const purpose = auditText(
      req.get('X-Audit-Purpose') ||
        req.query.purpose ||
        (req.body as Record<string, unknown> | undefined)?.purpose,
      'audit purpose',
      2000,
    );
    const sensitive = await authorize(actorId, companyId, 'audit:records:read-sensitive');
    return { ...auditScope(companyId), actorId, purpose, sensitive, ownOnly };
  }
  const route = (
    method: 'get' | 'post',
    path: string,
    permission: string,
    handler: (a: AuditAccess, req: Request, res: Response) => Promise<unknown>,
    allowOwn = false,
  ) => {
    router[method](path, async (req, res, next) => {
      try {
        const a = await access(req, permission, allowOwn);
        const data = await handler(a, req, res);
        if (!res.headersSent) res.json({ success: true, data });
      } catch (error) {
        if (error instanceof z.ZodError) {
          next(auditFailure('Invalid audit request.'));
          return;
        }
        next(error);
      }
    });
  };
  const read = platform ? 'audit:records:read-platform' : 'audit:records:read-tenant';
  route(
    'get',
    '/records',
    read,
    (a, req) => services.query.search(a, querySchema.parse(req.query)),
    true,
  );
  route('get', '/records/:id', read, (a, req) => services.query.get(a, id(req)), true);
  route('get', '/resources/:type/:resourceId/history', 'audit:resources:history', (a, req) =>
    services.query.search(a, {
      ...querySchema.parse(req.query),
      resourceType: text.parse(req.params.type),
      resourceId: text.parse(req.params.resourceId),
    }),
  );
  route('get', '/actors/:actorId/activity', 'audit:actors:activity', (a, req) =>
    services.query.search(a, {
      ...querySchema.parse(req.query),
      actorId: text.parse(req.params.actorId),
    }),
  );
  route('get', '/correlations/:correlationId', 'audit:correlations:read', (a, req) =>
    services.query.search(a, {
      ...querySchema.parse(req.query),
      correlationId: text.parse(req.params.correlationId),
    }),
  );
  route('get', '/dashboard', read, (a) => services.query.dashboard(a));
  route('get', '/reports', 'audit:reports:read', (a) => services.query.dashboard(a));
  const objectList = (path: string, kind: AuditObjectKind, permission: string) =>
    route('get', path, permission, async (a, req) => {
      const limit = z.coerce.number().int().min(1).max(200).default(50).parse(req.query.limit);
      const offset = z.coerce.number().int().min(0).default(0).parse(req.query.offset);
      const rows = (await services.core.list(a, kind)).filter(
        (row) => a.sensitive || row.data.sensitive !== true,
      );
      await services.core.notice(a, a.actorId, 'audit.management.queried', kind, {
        purpose: a.purpose,
        offset,
        limit,
      });
      return { items: rows.slice(offset, offset + limit), total: rows.length };
    });
  const objectGet = (path: string, kind: AuditObjectKind, permission: string) =>
    route('get', path, permission, async (a, req) => {
      const row = await services.core.objectData(a, kind, id(req));
      if (row.data.sensitive === true && !a.sensitive)
        throw auditFailure('Sensitive audit permission required.', 403);
      await services.core.notice(a, a.actorId, 'audit.management.read', row.id, {
        purpose: a.purpose,
        kind,
      });
      return row;
    });
  objectList('/investigations', 'INVESTIGATION', 'audit:investigations:read');
  objectGet('/investigations/:id', 'INVESTIGATION', 'audit:investigations:read');
  route('post', '/investigations', 'audit:investigations:create', (a, req) => {
    const v = z.object({ title: text, reason }).parse(req.body);
    return services.investigations.open(a, v.title, v.reason);
  });
  route('post', '/investigations/:id/evidence', 'audit:investigations:update', (a, req) =>
    services.investigations.addEvidence(
      a,
      id(req),
      z.object({ recordIds: identifiers }).parse(req.body).recordIds,
    ),
  );
  route('post', '/investigations/:id/close', 'audit:investigations:close', (a, req) =>
    services.investigations.close(a, id(req), z.object({ reason }).parse(req.body).reason),
  );
  route('post', '/evidence-packages', 'audit:evidence:create', (a, req) => {
    const v = z
      .object({ recordIds: identifiers, investigationId: z.string().uuid().optional() })
      .parse(req.body);
    return services.evidence.create(a, v.recordIds, v.investigationId);
  });
  objectGet('/evidence-packages/:id', 'EVIDENCE', 'audit:evidence:read');
  route('post', '/evidence-packages/:id/verify', 'audit:evidence:verify', (a, req) =>
    services.evidence.verify(a, id(req)),
  );
  const download = (res: Response, bytes: Buffer, name: string) => {
    res
      .set({
        'Content-Type': 'application/json',
        'Content-Disposition': `attachment; filename="${name}.json"`,
        'Cache-Control': 'no-store',
        'X-Content-Type-Options': 'nosniff',
      })
      .send(bytes);
  };
  route('get', '/evidence-packages/:id/download', 'audit:evidence:download', async (a, req, res) =>
    download(res, await services.evidence.download(a, id(req)), `audit-evidence-${id(req)}`),
  );
  objectList('/exports', 'EXPORT', 'audit:exports:read');
  objectGet('/exports/:id', 'EXPORT', 'audit:exports:read');
  route('post', '/exports', 'audit:exports:create', (a, req) =>
    services.exports.request(
      a,
      querySchema.parse(z.object({ filter: querySchema.default({}) }).parse(req.body).filter),
    ),
  );
  for (const [suffix, approved] of [
    ['approve', true],
    ['reject', false],
  ] as const)
    route('post', `/exports/:id/${suffix}`, `audit:exports:${suffix}`, (a, req) =>
      services.exports.decide(a, id(req), approved, z.object({ reason }).parse(req.body).reason),
    );
  route('get', '/exports/:id/download', 'audit:exports:download', async (a, req, res) =>
    download(res, await services.exports.download(a, id(req)), `audit-export-${id(req)}`),
  );
  objectList('/admin/policies', 'POLICY', 'audit:policies:read');
  route('post', '/admin/policies', 'audit:policies:manage', (a, req) =>
    services.monitor.policy(
      a,
      z
        .object({
          code: text,
          eventType: text.optional(),
          severity: z.enum(['CRITICAL', 'HIGH', 'MEDIUM', 'LOW']),
          sensitive: z.boolean(),
          reason,
        })
        .parse(req.body),
    ),
  );
  objectList('/admin/integrity', 'INTEGRITY_RUN', 'audit:integrity:read');
  route('post', '/admin/integrity/verify', 'audit:integrity:verify', (a) =>
    services.integrity.verify(a, a.actorId),
  );
  route('post', '/admin/integrity/checkpoints', 'audit:integrity:verify', (a) =>
    services.integrity.checkpoint(a),
  );
  objectList('/admin/ingestion-failures', 'INGESTION_FAILURE', 'audit:administration:read');
  route('post', '/admin/ingestion-failures/:id/retry', 'audit:administration:manage', (a, req) =>
    services.monitor.retry(a, id(req), true),
  );
  objectList('/admin/reconciliation', 'RECONCILIATION', 'audit:administration:read');
  route('post', '/admin/reconciliation', 'audit:administration:manage', (a) =>
    services.monitor.drain(a, true),
  );
  objectList('/admin/retention', 'RETENTION', 'audit:retention:read');
  objectList('/admin/retention/executions', 'RETENTION_RUN', 'audit:retention:read');
  route('post', '/admin/retention', 'audit:retention:manage', (a, req) =>
    services.retention.policy(
      a,
      z
        .object({
          category: z.enum(auditCategories),
          days: z.number().int().positive().max(365000),
          legalReference: reason,
          reason,
        })
        .parse(req.body),
    ),
  );
  route('post', '/admin/retention/:id/execute', 'audit:retention:manage', (a, req) =>
    services.retention.execute(a, id(req)),
  );
  objectList('/admin/legal-holds', 'LEGAL_HOLD', 'audit:legal-holds:read');
  route('post', '/admin/legal-holds', 'audit:legal-holds:create', (a, req) =>
    services.retention.hold(
      a,
      z
        .object({
          reason,
          recordIds: identifiers.optional(),
          resourceType: text.optional(),
          resourceId: text.optional(),
          wholeScope: z.boolean().optional(),
        })
        .parse(req.body),
    ),
  );
  route('post', '/admin/legal-holds/:id/release', 'audit:legal-holds:release', (a, req) =>
    services.retention.release(a, id(req), z.object({ reason }).parse(req.body).reason),
  );
  objectList('/admin/alerts', 'ALERT', 'audit:alerts:read');
  objectList('/admin/alert-rules', 'ALERT_RULE', 'audit:alerts:read');
  route('post', '/admin/alert-rules', 'audit:alerts:manage', (a, req) =>
    services.monitor.alertRule(
      a,
      z
        .object({
          code: text,
          eventType: text.optional(),
          outcome: z.enum(['SUCCESS', 'FAILURE', 'DENIED', 'PARTIAL', 'CANCELLED']).optional(),
          severity: z.enum(['CRITICAL', 'HIGH', 'MEDIUM', 'LOW']).optional(),
          threshold: z.number().int().min(1).max(1000),
          windowMinutes: z.number().int().min(1).max(1440),
        })
        .parse(req.body),
    ),
  );
  route('post', '/admin/alerts/:id/acknowledge', 'audit:alerts:manage', (a, req) =>
    services.core.repository.transaction(a, async (tx) => {
      const row = await services.core.requireObject(a, 'ALERT', id(req), tx);
      const data = z.object({ reason }).parse(req.body);
      const result = await services.core.repository.updateObject(
        row,
        {
          status: 'ACKNOWLEDGED',
          data: { ...row.data, acknowledgedBy: a.actorId, reason: data.reason },
        },
        tx,
      );
      await services.core.notice(
        a,
        a.actorId,
        'audit.alert.acknowledged',
        row.id,
        { reason: data.reason },
        tx,
      );
      return result;
    }),
  );
  return router;
}

import { Router, Request, Response, NextFunction } from 'express';

import { AuditLogController } from '../controllers/audit-log.controller';
import { queryAuditLogsSchema } from '../schemas/audit-log.schema';

type Middleware = (req: Request, res: Response, next: NextFunction) => void;

/**
 * Rotas do trilho de auditoria.
 *
 * Todas exigem `req.tenant` (resolvido pelos middlewares de tenant)
 * e a permissão `audit.read` no âmbito da empresa.
 */
export const createAuditRoutes = (
  controller: AuditLogController,
  requirePermission: Middleware,
): Router => {
  const router = Router();

  /**
   * @swagger
   * /company/audit-logs:
   *   get:
   *     summary: Consultar trilho de auditoria da empresa
   *     description: Lista paginada dos registos de auditoria do tenant autenticado.
   *     tags: [Audit]
   *     parameters:
   *       - in: query
   *         name: page
   *         schema: { type: integer, minimum: 1, default: 1 }
   *       - in: query
   *         name: limit
   *         schema: { type: integer, minimum: 1, maximum: 100, default: 20 }
   *       - in: query
   *         name: action
   *         schema: { type: string }
   *       - in: query
   *         name: entityType
   *         schema: { type: string }
   *       - in: query
   *         name: entityId
   *         schema: { type: string }
   *       - in: query
   *         name: from
   *         schema: { type: string, format: date-time }
   *       - in: query
   *         name: to
   *         schema: { type: string, format: date-time }
   *     responses:
   *       200:
   *         description: Lista de registos de auditoria
   *       400:
   *         description: Contexto de empresa em falta ou filtros inválidos
   *       401:
   *         description: Não autenticado
   *       403:
   *         description: Sem permissão audit.read
   */
  router.get(
    '/audit-logs',
    requirePermission,
    (req, res, next) => {
      try {
        const parsed = queryAuditLogsSchema.parse(req.query);
        req.query = parsed as unknown as Request['query'];
        next();
      } catch (error) {
        next(error);
      }
    },
    (req, res) => controller.list(req, res),
  );

  return router;
};
